arguments.file_text:
@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              title="@star star(s)">
            &#9733;
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<div class="rating-summary">
    @if (CurrentRating > 0)
    {
        <span>Average: @CurrentRating.ToString("0.0") / 5 (@RatingCount ratings)</span>
    }
    else
    {
        <span>No ratings yet</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedRating = stars;
        RecipeStore.Rate(RecipeId, stars);

        var recipe = RecipeStore.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }

        _submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 1rem 0 0.5rem;
}

.rating-label {
    margin-right: 0.5rem;
    font-weight: 500;
}

.star {
    font-size: 1.75rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

.rating-thanks {
    margin-left: 0.75rem;
    color: #28a745;
    font-weight: 500;
}

.rating-summary {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

