{"path": "/tmp/sv-9e545a06be804c54967ba1c6676560bb/RecipeShare/Models/Recipe.cs", "file_text": "using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nMozzarella cheese\nFresh basil\nSan Marzano tomatoes\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil and olive oil" },
        new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCream\nTomato sauce\nOnion\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or pan-fry chicken\n3. Sauté onions, garlic, ginger\n4. Add tomato sauce and spices\n5. Simmer with cream\n6. Add chicken pieces and cook 10 min" },
        new() { Id = 3, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti al dente\n2. Crisp guanciale in pan\n3. Mix eggs, cheese, and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, add egg mixture\n6. Toss until creamy" },
        new() { Id = 4, Title = "Tacos al Pastor", Category = "Mexican", Ingredients = "Pork shoulder\nPineapple\nAchiote paste\nCorn tortillas\nOnion\nCilantro\nLime", Steps = "1. Marinate pork in achiote and pineapple juice\n2. Grill pork until charred\n3. Slice thinly\n4. Warm tortillas\n5. Assemble with onion, cilantro, pineapple\n6. Squeeze lime on top" },
        new() { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture\n4. Add flour and vanilla\n5. Pour into greased ramekins\n6. Bake at 425°F for 12 minutes" },
        new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño\n4. Mix all ingredients\n5. Add lime juice and salt\n6. Serve immediately" },
        new() { Id = 7, Title = "Tiramisu", Category = "Desserts", Ingredients = "Ladyfinger biscuits\nMascarpone\nEspresso\nEggs\nSugar\nCocoa powder\nMarsala wine", Steps = "1. Brew espresso and cool\n2. Separate eggs; beat yolks with sugar\n3. Fold in mascarpone\n4. Whip whites and fold in\n5. Dip ladyfingers in espresso\n6. Layer biscuits and cream\n7. Dust with cocoa, refrigerate 4 hours" },
        new() { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken breast\nButter\nCream\nTomato puree\nGaram masala\nFenugreek leaves\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or bake chicken\n3. Make sauce: butter, garlic, ginger, tomato\n4. Add cream and fenugreek\n5. Simmer and add chicken\n6. Serve with naan" },
    };

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public static void Rate(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalRating = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalRating / recipe.RatingCount;
    }
}
"}

