{"file_text": "@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <a href="/">Home</a> &rsaquo;
    @if (recipe is not null)
    {
        <a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a>
        <span> &rsaquo; @recipe.Title</span>
    }
</nav>

@if (recipe is null)
{
    <h1>Recipe not found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>

    <StarRating RecipeId="@recipe.Id"
                CurrentRating="@recipe.AverageRating"
                RatingCount="@recipe.RatingCount" />

    <section class="recipe-section">
        <h2>🥘 Ingredients</h2>
        <ul>
            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>📋 Steps</h2>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}
