@page "/"
@using RecipeShare.Models

<PageTitle>RecipeShare - Home</PageTitle>

<div class="hero">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes from around the world</p>
</div>

<h2>Browse by Category</h2>

<div class="category-grid">
    @foreach (var category in RecipeStore.Categories)
    {
        <a class="category-card" href="/recipes/@category.ToLower()">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <span class="category-name">@category</span>
            <span class="recipe-count">@RecipeStore.ByCategory(category).Count() recipes</span>
        </a>
    }
</div>

<h2>Recent Recipes</h2>
<div class="recipe-list">
    @foreach (var recipe in RecipeStore.All.TakeLast(4).Reverse())
    {
        <div class="recipe-preview">
            <a href="/recipe/@recipe.Id">@recipe.Title</a>
            <span class="badge">@recipe.Category</span>
        </div>
    }
</div>

