toolArgs.file_text:
@page "/submit"
@using RecipeShare.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="success-message">
        <h2>✅ Recipe submitted!</h2>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added.</p>
        <a href="/recipe/@_newId">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" rows="6"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. ..." />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private Recipe _model = new();
    private bool _submitted;
    private int _newId;

    private void HandleSubmit()
    {
        RecipeStore.Add(_model);
        _newId = _model.Id;
        _submitted = true;
    }
}

h1 {
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.4rem;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
}

.btn-submit {
    background: #667eea;
    color: white;
    border: none;
    padding: 0.7rem 1.5rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-submit:hover {
    background: #5a6fd6;
}

.success-message {
    padding: 1.5rem;
    background: #e8f5e9;
    border-radius: 10px;
    border: 1px solid #c8e6c9;
}

.success-message a {
    color: #667eea;
    font-weight: 500;
}

::deep .validation-message {
    color: #d32f2f;
    font-size: 0.85rem;
}

